<script setup lang="ts">
import { computed, ref } from 'vue'; import { Head, router } from '@inertiajs/vue3'; import { Download, Printer, Search } from 'lucide-vue-next';
import Layout from '../components/Layout.vue';import { grade } from '../lib';
const props=defineProps<{classrooms:any[];report:any}>();const search=ref(''),moduleFilter=ref('');
const rows=computed(()=>props.report?.rows.filter((r:any)=>(!moduleFilter.value||r.module===moduleFilter.value)&&r.student.toLowerCase().includes(search.value.toLowerCase()))??[]);const selected=ref(props.report?.classroom.id??'');const detail=ref<any>(null);
function print(){window.print()}
</script>
<template><Layout><Head title="Evaluaciones"/><div class="topline"><span>Seguimiento académico</span><span>RETOS → EVALUACIONES → CURSO</span></div><header class="page-heading"><div><p class="eyebrow">LA EVOLUCIÓN DEL APRENDIZAJE</p><h1>Cada Evaluación cuenta<span class="accent">.</span></h1><p class="muted">Retos ponderados en cada Evaluación. Media de Evaluaciones para el curso.</p></div><div class="actions"><a v-if="report" class="button" :href="`/reports?classroom=${selected}&format=csv`"><Download :size="17"/>CSV</a><button class="button" @click="print"><Printer :size="17"/>Imprimir / PDF</button></div></header><div class="matrix-toolbar"><label>Clase<select v-model="selected" @change="router.get('/reports',{classroom:selected})"><option v-for="c in classrooms" :value="c.id">{{c.name}} · {{c.academic_year.name}}</option></select></label><label>Módulo<select v-model="moduleFilter"><option value="">Todos</option><option v-for="m in report?.classroom.modules" :value="m.code">{{m.code}}</option></select></label><div class="search-box"><Search :size="17"/><input v-model="search" placeholder="Buscar estudiante…" aria-label="Buscar estudiante"/></div></div><p class="notice info">Vista de seguimiento. Una nota pendiente mantiene pendiente su Evaluación y la media del curso. Haz clic en una Evaluación para consultar los retos y pesos utilizados.</p><div class="table-scroll"><table><thead><tr><th>ESTUDIANTE</th><th>MÓDULO</th><th v-for="p in report?.classroom.academic_year.periods">{{p.name}}</th><th>MEDIA DEL CURSO</th></tr></thead><tbody><tr v-for="r in rows"><td>{{r.student}}</td><td><span class="module-chip">{{r.module}}</span></td><td v-for="p in r.periods"><button class="grade-link" @click="detail={...p,student:r.student,module:r.module}">{{p.not_enrolled?'No matriculado':grade(p.grade)}}</button></td><td class="challenge-total bold">{{r.not_enrolled?'No matriculado':grade(r.annual)}}</td></tr></tbody></table></div><div v-if="!report" class="empty-state">Crea un curso y una clase para comenzar el seguimiento.</div><section v-if="detail" class="panel report-detail"><div class="actions"><h2>{{detail.student}} · {{detail.module}} · {{detail.name}}</h2><button class="button" @click="detail=null">Cerrar detalle</button></div><div v-for="ch in detail.challenges" class="breakdown-row"><a :href="`/challenges/${ch.id}`">{{ch.name}}</a><span>Peso {{ch.weight}}</span><strong>{{ch.not_enrolled?'No matriculado':grade(ch.grade)}}</strong></div><p v-if="!detail.challenges.length" class="muted">No hay retos de este módulo en la Evaluación.</p><div class="breakdown-row total"><span>Media ponderada de los retos</span><strong>{{detail.not_enrolled?'No matriculado':grade(detail.grade)}}</strong></div></section></Layout></template>
